graphql.query:
query($queryStr: String!, $cursor: String) {
  search(query: $queryStr, type: ISSUE, first: 50, after: $cursor) {
    issueCount
    pageInfo {
      hasNextPage
      endCursor
    }
    nodes {
      ... on PullRequest {
        number
        title
        url
        createdAt
        merged
        mergedAt
        mergedBy {
          login
        }
        author {
          login
        }
        comments {
          totalCount
        }
        reviews {
          totalCount
        }
        additions
        deletions
        changedFiles
        repository {
          name
          owner {
            login
          }
          createdAt
          isFork
          stargazerCount
          forkCount
        }
      }
    }
  }
}
